-- Reference only. Executable versioned migrations are in drizzle/, generated by drizzle-kit.
-- Shared lobby tables only; shared account/trip ids are supplied by the team adapter.
create table if not exists shared_lobby_posts (
  rowid bigserial unique,
  id text primary key,
  trip_id text not null unique,
  owner_id text not null,
  owner_name text not null,
  origin text not null,
  destination text not null,
  start_date text not null,
  end_date text not null check (end_date >= start_date),
  member_count integer not null check (member_count > 0),
  note text not null,
  published_at text not null
);

-- A request to join a trip. The applicant is a person; the trip is the group they are asking to join.
--
-- The applicant is not a member of the trip yet, so their name is copied in here: a request has to keep
-- saying who asked, even after it is closed.
create table if not exists shared_lobby_requests (
  rowid bigserial unique,
  id text primary key,
  post_id text not null,
  trip_id text not null,
  applicant_id text not null,
  applicant_name text not null,
  message text not null,
  status text not null check (status in ('pending', 'accepted', 'declined')),
  score integer not null check (score between 0 and 100),
  created_at text not null,
  responded_at text,
  closed_by text check (closed_by in ('answerer', 'gone', 'asked', 'left'))
);
create index if not exists shared_lobby_requests_trip on shared_lobby_requests(trip_id);
create index if not exists shared_lobby_requests_applicant on shared_lobby_requests(applicant_id);
-- One person asks once: a pending request stands in the way of asking again, an answered one doesn't.
create unique index if not exists shared_lobby_one_pending_request_per_person_trip on shared_lobby_requests(applicant_id, trip_id)
  where status = 'pending';

-- The chat group of a trip. Every member of the trip is in it, and it goes on for as long as the trip does.
create table if not exists shared_lobby_messages (
  rowid bigserial unique,
  id text primary key,
  trip_id text not null,
  sender_id text not null,
  sender_name text not null,
  body text not null check (length(trim(body)) between 1 and 2000),
  sent_at text not null
);
create index if not exists shared_lobby_messages_trip on shared_lobby_messages(trip_id, sent_at);

-- Removing a publication closes the requests waiting on it. An accepted request has already put the
-- applicant in the trip, so it stands.

create or replace function shared_lobby_close_publication() returns trigger language plpgsql as $$
begin
 update shared_lobby_requests set status='declined', closed_by='gone', responded_at=to_char(clock_timestamp() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') where status='pending' and post_id=OLD.id;
 return OLD;
end $$;
drop trigger if exists shared_lobby_close_publication on shared_lobby_posts;
create trigger shared_lobby_close_publication after delete on shared_lobby_posts for each row execute function shared_lobby_close_publication();
